-- Trang chính sách (CMS) — chạy MỘT lần trên production nếu không dùng `php artisan migrate`.
-- Tương đương 2 migration 2026_11_16_000100_create_legal_pages_table + 2026_11_17_000100_turn_legal_pages_into_cms.
-- An toàn khi chạy lại: CREATE TABLE IF NOT EXISTS, INSERT IGNORE theo slug (không ghi đè trang admin đã sửa),
-- và chỉ ghi vào bảng migrations nếu chưa có — để sau này `php artisan migrate` không tạo lại bảng.
-- Sinh tự động từ DB local ngày 17/11/2026. Nên sao lưu DB trước khi chạy.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `legal_pages` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(50) NOT NULL,
  `title` varchar(191) NOT NULL DEFAULT '',
  `meta_description` varchar(300) DEFAULT NULL,
  `is_system` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` smallint(5) unsigned NOT NULL DEFAULT 0,
  `content` longtext DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `legal_pages_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT IGNORE INTO `legal_pages` (`slug`, `title`, `meta_description`, `is_system`, `is_active`, `sort_order`, `content`, `created_at`, `updated_at`) VALUES
('dieu-khoan-su-dung', 'Điều khoản sử dụng', 'Điều khoản sử dụng dịch vụ học Toán trực tuyến Math AI: tài khoản, gói học, thanh toán, quyền và nghĩa vụ.', 1, 1, 1, NULL, '2026-11-17 08:51:32', '2026-11-17 08:51:32'),
('chinh-sach-bao-mat', 'Chính sách bảo mật', 'Math AI thu thập, sử dụng và bảo vệ dữ liệu của học sinh, phụ huynh, giáo viên như thế nào.', 1, 1, 2, NULL, '2026-11-17 08:51:32', '2026-11-17 08:51:32'),
('chinh-sach-gia', 'Chính sách giá', 'Nguyên tắc niêm yết giá, mã giảm giá và thay đổi giá gói học tại Math AI.', 0, 1, 3, '<h2>1. Niêm yết giá</h2><ul><li>Giá từng gói học được niêm yết công khai tại trang <a href=\"/goi-hoc\">Gói học</a>, bằng <strong>đồng Việt Nam (VNĐ)</strong>.</li><li>Giá hiển thị là giá đã bao gồm thuế (nếu có). Bạn không phải trả thêm khoản nào ngoài số tiền ghi ở bước thanh toán.</li><li>Có gói <strong>miễn phí</strong> với quyền lợi giới hạn; không cần thẻ tín dụng để dùng.</li></ul><h2>2. Mã giảm giá</h2><ul><li>Số tiền được giảm do hệ thống tính theo điều kiện của từng mã và hiển thị trước khi bạn thanh toán.</li><li>Mã có thời hạn và số lượt dùng giới hạn; mã đã hết hạn hoặc hết lượt không dùng được.</li></ul><h2>3. Thay đổi giá</h2><ul><li>Chúng tôi có thể điều chỉnh giá và quyền lợi gói; giá mới chỉ áp dụng cho các đơn <strong>tạo sau</strong> thời điểm thay đổi.</li><li>Gói bạn đã mua không bị ảnh hưởng bởi việc đổi giá.</li></ul><h2>4. Không phí ẩn, không tự gia hạn</h2><p class=\"mb-0\"> Chúng tôi không thu phí đăng ký hay phí duy trì tài khoản và không tự động gia hạn gói. Chi tiết cách thanh toán xem <a href=\"/chinh-sach-thanh-toan\">Chính sách thanh toán</a>; điều kiện hoàn tiền xem <a href=\"/chinh-sach-giao-nhan-hoan-huy\">Chính sách giao nhận và hoàn hủy khóa học</a>. </p>', '2026-10-29 00:00:00', '2026-10-29 00:00:00'),
('chinh-sach-thanh-toan', 'Chính sách thanh toán', 'Các phương thức thanh toán, cách xác nhận giao dịch và bảo mật thanh toán tại Math AI.', 0, 1, 4, '<h2>1. Phương thức thanh toán</h2><p> Hiện hỗ trợ thanh toán qua <strong>MoMo, VNPAY hoặc Chuyển khoản QR</strong> (ví điện tử, thẻ ATM nội địa, Internet Banking, QR ngân hàng tùy cổng). Đơn vị tiền tệ là <strong>đồng Việt Nam (VNĐ)</strong>. </p><h2>2. Quy trình</h2><ol><li>Chọn gói tại trang <a href=\"/goi-hoc\">Gói học</a> và đăng nhập (hoặc đăng ký) tài khoản.</li><li>Kiểm tra gói, số tiền (đã áp mã giảm giá nếu có) rồi bấm thanh toán — bạn được chuyển sang cổng thanh toán.</li><li>Hoàn tất thanh toán trên cổng. Gói được kích hoạt khi <strong>cổng thanh toán báo về hệ thống</strong> rằng giao dịch thành công.</li><li>Biên nhận gửi về email tài khoản; lịch sử đơn xem trong tài khoản.</li></ol><h2>3. Xác nhận giao dịch</h2><ul><li>Chúng tôi chỉ kích hoạt gói dựa trên xác nhận từ cổng thanh toán — không dựa trên việc bạn quay lại trang web hay ảnh chụp màn hình.</li><li>Số tiền thanh toán do hệ thống tính từ giá niêm yết và mã giảm giá hợp lệ; không thể sửa từ phía trình duyệt.</li><li>Bị trừ tiền nhưng gói chưa kích hoạt: xem mục 1 của <a href=\"/chinh-sach-giao-nhan-hoan-huy\">Chính sách giao nhận và hoàn hủy</a>.</li></ul><h2>4. Bảo mật thanh toán</h2><ul><li>Thông tin thẻ, tài khoản ngân hàng và mật khẩu ví được nhập trên trang của cổng thanh toán; <strong>chúng tôi không lưu</strong> các thông tin này.</li><li>Chúng tôi chỉ lưu mã đơn, số tiền, trạng thái và mã giao dịch của cổng để đối soát.</li><li>Chỉ thanh toán qua đường dẫn do website này chuyển tới. Chúng tôi không bao giờ yêu cầu bạn gửi mật khẩu, mã OTP qua tin nhắn hay điện thoại.</li></ul><h2>5. Mã giảm giá và gia hạn</h2><ul><li>Mã giảm giá có điều kiện, thời hạn và số lượt dùng riêng; mỗi đơn dùng tối đa một mã.</li><li>Gói <strong>không tự động gia hạn</strong> — chúng tôi không tự trừ tiền kỳ sau.</li></ul><h2>6. Liên hệ khi có vấn đề thanh toán</h2><p class=\"mb-0\">Gửi mã đơn tới <a href=\"mailto:danh@famemedia.vn\">danh@famemedia.vn</a> hoặc dùng <a href=\"/ho-tro\">biểu mẫu hỗ trợ</a>.</p>', '2026-10-29 00:00:00', '2026-10-29 00:00:00'),
('chinh-sach-giao-nhan-hoan-huy', 'Chính sách giao nhận và hoàn hủy khóa học', 'Cách gói học được kích hoạt sau khi thanh toán và điều kiện hủy, hoàn tiền tại Math AI.', 0, 1, 5, '<p class=\"text-secondary\"> Công ty TNHH Fame Media cung cấp dịch vụ học trực tuyến, <strong>không có hàng hoá giao tận nơi</strong>. Trang này nói rõ gói học được \"giao\" như thế nào, khi nào được hủy và hoàn tiền. </p><h2>1. Giao nhận (kích hoạt gói học)</h2><ul><li>Gói học được kích hoạt <strong>ngay</strong> khi cổng thanh toán xác nhận giao dịch thành công; không cần chờ duyệt thủ công.</li><li>Quyền lợi gói gắn với tài khoản học sinh được chọn lúc mua. Bạn xem gói đang dùng và ngày hết hạn tại mục <a href=\"/goi-hoc\">Gói học</a> sau khi đăng nhập.</li><li>Mua thêm gói cùng hạng khi gói cũ còn hạn: thời hạn được <strong>cộng nối tiếp</strong>, không mất phần còn lại.</li><li>Biên nhận thanh toán gửi về email của tài khoản. Nếu đã bị trừ tiền mà sau 30 phút gói chưa được kích hoạt, hãy gửi mã giao dịch cho chúng tôi — chúng tôi đối soát với cổng thanh toán và kích hoạt hoặc hoàn tiền đầy đủ.</li></ul><h2>2. Hủy gói</h2><ul><li>Gói <strong>không tự động gia hạn</strong>, vì vậy bạn không cần \"hủy đăng ký\" để tránh bị trừ tiền kỳ sau.</li><li>Đơn đang chờ thanh toán quá 24 giờ được hệ thống tự hủy; không phát sinh phí.</li><li>Muốn ngừng sử dụng, bạn có thể yêu cầu xóa tài khoản bất cứ lúc nào (xem <a href=\"/chinh-sach-bao-mat\">Chính sách bảo mật</a>). Phần gói còn lại chỉ được hoàn khi đáp ứng điều kiện ở mục 3.</li></ul><h2>3. Hoàn tiền</h2><p>Chúng tôi xem xét hoàn tiền khi có một trong các trường hợp sau:</p><ul><li><strong>Lỗi từ phía hệ thống:</strong> bị trừ tiền nhưng gói không được kích hoạt, bị trừ tiền nhiều lần cho cùng một đơn.</li><li><strong>Đổi ý:</strong> gửi yêu cầu trong vòng <strong>7 ngày</strong> kể từ khi thanh toán và đã sử dụng <strong>dưới 20%</strong> thời hạn gói.</li></ul><p>Không hoàn tiền khi tài khoản bị khóa do vi phạm <a href=\"/dieu-khoan-su-dung\">Điều khoản sử dụng</a>.</p><h2>4. Cách gửi yêu cầu và thời gian xử lý</h2><ul><li>Gửi email tới <a href=\"mailto:danh@famemedia.vn\">danh@famemedia.vn</a> hoặc dùng <a href=\"/ho-tro\">biểu mẫu hỗ trợ</a>, kèm <strong>mã đơn</strong> và email tài khoản.</li><li>Chúng tôi phản hồi trong <strong>7 ngày làm việc</strong>.</li><li>Tiền được hoàn <strong>về đúng phương thức đã thanh toán</strong> qua cổng thanh toán (MoMo, VNPAY hoặc Chuyển khoản QR); thời gian tiền về tài khoản phụ thuộc ngân hàng/ví, thường vài ngày làm việc.</li><li>Có thể hoàn một phần số tiền. Sau khi hoàn tiền, quyền lợi gói tương ứng sẽ được thu hồi.</li></ul>', '2026-10-29 00:00:00', '2026-10-29 00:00:00'),
('giai-quyet-khieu-nai', 'Tiếp nhận và giải quyết phản ánh, khiếu nại', 'Kênh và quy trình tiếp nhận, giải quyết phản ánh, khiếu nại của người dùng Math AI.', 0, 1, 6, '<p class=\"text-secondary\"> Chúng tôi coi mọi phản ánh là cơ hội để làm tốt hơn. Trang này nêu rõ gửi ở đâu và được xử lý ra sao. </p><h2>1. Kênh tiếp nhận</h2><ul><li><strong>Biểu mẫu:</strong><a href=\"/ho-tro\">Gửi yêu cầu hỗ trợ</a> hoặc <a href=\"/ho-tro?loai=content_error\">Báo lỗi nội dung</a>.</li><li><strong>Email:</strong><a href=\"mailto:danh@famemedia.vn\">danh@famemedia.vn</a></li><li><strong>Điện thoại:</strong> 0834 309 319</li><li><strong>Trực tiếp / thư tín:</strong> 38/3/1 Trần Văn Mười, xã Bà Điểm, TPHCM</li></ul><h2>2. Thông tin nên có trong phản ánh</h2><ul><li>Họ tên, email tài khoản (hoặc số điện thoại liên hệ).</li><li>Nội dung vấn đề, thời điểm xảy ra, mã đơn hàng nếu liên quan thanh toán; ảnh chụp màn hình nếu có.</li><li>Mong muốn xử lý (sửa lỗi, hoàn tiền, xóa dữ liệu…).</li></ul><h2>3. Quy trình và thời hạn</h2><ol><li><strong>Tiếp nhận:</strong> chúng tôi xác nhận đã nhận phản ánh trong <strong>1 ngày làm việc</strong> và cấp mã theo dõi (số phiếu hỗ trợ).</li><li><strong>Xác minh:</strong> kiểm tra dữ liệu hệ thống, đối soát với cổng thanh toán (nếu liên quan), liên hệ bạn khi cần thêm thông tin.</li><li><strong>Giải quyết:</strong> phản hồi kết quả trong <strong>7 ngày làm việc</strong>; vụ việc phức tạp tối đa <strong>15 ngày làm việc</strong> và chúng tôi báo trước lý do kéo dài.</li><li><strong>Theo dõi:</strong> bạn xem trạng thái phiếu và nhận thông báo khi phiếu được xử lý.</li></ol><h2>4. Khi chưa đồng ý với kết quả</h2><ul><li>Bạn có thể trả lời lại phiếu để yêu cầu xem xét lần hai; phiếu được chuyển cho người phụ trách cấp cao hơn.</li><li>Chúng tôi ưu tiên thương lượng. Nếu không đạt được thỏa thuận, bạn có quyền gửi khiếu nại tới cơ quan quản lý nhà nước có thẩm quyền hoặc khởi kiện tại tòa án theo quy định pháp luật Việt Nam.</li></ul><h2>5. Bảo mật thông tin người phản ánh</h2><p class=\"mb-0\"> Thông tin trong phản ánh chỉ dùng để xử lý vụ việc và không chia sẻ cho bên thứ ba ngoài phạm vi cần thiết (ví dụ cổng thanh toán khi đối soát giao dịch). Xem <a href=\"/chinh-sach-bao-mat\">Chính sách bảo mật</a>. </p>', '2026-10-29 00:00:00', '2026-10-29 00:00:00'),
('dieu-kien-han-che-dich-vu', 'Các điều kiện hạn chế cung cấp dịch vụ', 'Những trường hợp Math AI giới hạn hoặc tạm ngừng cung cấp dịch vụ cho người dùng.', 0, 1, 7, '<p class=\"text-secondary\"> Để dịch vụ an toàn và công bằng cho học sinh, một số trường hợp chúng tôi sẽ giới hạn hoặc tạm ngừng cung cấp dịch vụ. </p><h2>1. Điều kiện về người dùng</h2><ul><li>Học sinh <strong>chưa đủ 15 tuổi</strong> cần cha mẹ hoặc người giám hộ đồng ý khi tạo và sử dụng tài khoản.</li><li>Tài khoản giáo viên phải được quản trị viên duyệt trước khi dùng các chức năng giảng dạy.</li><li>Mỗi tài khoản dành cho một người; không dùng chung tài khoản trả phí.</li></ul><h2>2. Giới hạn theo gói học</h2><ul><li>Phạm vi bài học, số bài luyện tập, đề kiểm tra và số lượt hỏi AI mỗi ngày phụ thuộc gói đang dùng; chi tiết tại <a href=\"/goi-hoc\">Gói học</a>.</li><li>Hết hạn gói, tài khoản trở về gói miễn phí và dữ liệu học tập vẫn được giữ.</li></ul><h2>3. Giới hạn trong khi làm bài kiểm tra</h2><ul><li>Trợ lý AI bị khóa hoàn toàn trong lúc làm bài kiểm tra để bảo đảm công bằng.</li><li>Thời gian làm bài do hệ thống quyết định; hết giờ bài được tự động nộp.</li></ul><h2>4. Hạn chế do vi phạm</h2><p>Chúng tôi có thể cảnh báo, giới hạn tính năng hoặc khóa tài khoản khi phát hiện:</p><ul><li>Sao chép, tải hàng loạt hoặc phát tán lại nội dung; dùng công cụ tự động cào dữ liệu hoặc gây quá tải hệ thống.</li><li>Gian lận trong kiểm tra, dùng nhiều tài khoản, nhờ người khác làm hộ.</li><li>Đăng nội dung vi phạm pháp luật hoặc không phù hợp với môi trường giáo dục; cố truy cập dữ liệu người khác.</li><li>Gian lận thanh toán hoặc lạm dụng mã giảm giá.</li></ul><p>Chúng tôi nêu lý do khi khóa. Tài khoản bị khóa do vi phạm không được hoàn tiền phần gói còn lại.</p><h2>5. Gián đoạn ngoài tầm kiểm soát</h2><p class=\"mb-0\"> Dịch vụ có thể tạm gián đoạn khi bảo trì (có thông báo trước khi có thể), sự cố nhà cung cấp hạ tầng/cổng thanh toán, thiên tai, mất điện, mất mạng. Xem thêm <a href=\"/dieu-khoan-su-dung\">Điều khoản sử dụng</a>. </p>', '2026-10-29 00:00:00', '2026-10-29 00:00:00'),
('quyen-va-nghia-vu', 'Quyền và nghĩa vụ của các bên', 'Quyền và nghĩa vụ của người dùng và của Math AI khi sử dụng và cung cấp dịch vụ học Toán trực tuyến.', 0, 1, 8, '<p class=\"text-secondary\"> \"Chúng tôi\" là Công ty TNHH Fame Media; \"bạn\" là người dùng (học sinh, phụ huynh hoặc giáo viên). Trang này tóm tắt; điều khoản đầy đủ ở <a href=\"/dieu-khoan-su-dung\">Điều khoản sử dụng</a>. </p><h2>1. Quyền của bạn</h2><ul><li>Được sử dụng dịch vụ đúng gói đã đăng ký và đúng mô tả đã công bố.</li><li>Được bảo mật thông tin cá nhân và dữ liệu học tập theo <a href=\"/chinh-sach-bao-mat\">Chính sách bảo mật</a>; được xem, tải bản sao và yêu cầu xóa dữ liệu của mình.</li><li>Được hỗ trợ, phản ánh và khiếu nại theo <a href=\"/giai-quyet-khieu-nai\">quy trình tiếp nhận</a>.</li><li>Được hoàn tiền trong các trường hợp nêu ở <a href=\"/chinh-sach-giao-nhan-hoan-huy\">Chính sách giao nhận và hoàn hủy</a>.</li><li>Được ngừng sử dụng và yêu cầu xóa tài khoản bất cứ lúc nào.</li></ul><h2>2. Nghĩa vụ của bạn</h2><ul><li>Cung cấp thông tin đăng ký chính xác; giữ bí mật mật khẩu và báo ngay khi nghi ngờ bị lộ.</li><li>Không chia sẻ tài khoản trả phí; không sao chép, phát tán nội dung; không gian lận kiểm tra.</li><li>Thanh toán đúng số tiền của gói đã chọn qua các kênh chính thức.</li><li>Tôn trọng người dùng khác khi dùng tính năng Hỏi đáp và các nội dung công khai.</li></ul><h2>3. Quyền của chúng tôi</h2><ul><li>Thêm, sửa hoặc ngừng tính năng; điều chỉnh giá và quyền lợi gói cho các đơn mới.</li><li>Giới hạn hoặc khóa tài khoản khi vi phạm (xem <a href=\"/dieu-kien-han-che-dich-vu\">Các điều kiện hạn chế cung cấp dịch vụ</a>).</li><li>Sở hữu và bảo vệ bản quyền nội dung, giao diện của hệ thống.</li></ul><h2>4. Nghĩa vụ của chúng tôi</h2><ul><li>Cung cấp dịch vụ đúng mô tả; kích hoạt gói ngay khi thanh toán thành công.</li><li>Bảo mật thông tin cá nhân, không bán dữ liệu và không dùng dữ liệu học tập của học sinh để chạy quảng cáo.</li><li>Niêm yết giá công khai, không thu phí ẩn, không tự động gia hạn.</li><li>Tiếp nhận và giải quyết phản ánh, khiếu nại trong thời hạn đã công bố; hoàn tiền đúng điều kiện.</li><li>Báo trước khi có thay đổi ảnh hưởng tới gói đang trả phí.</li></ul><h2 class=\"mt-4\">5. Luật áp dụng</h2><p class=\"mb-0\">Pháp luật Việt Nam. Tranh chấp được ưu tiên giải quyết bằng thương lượng; nếu không đạt thỏa thuận thì do tòa án có thẩm quyền tại Việt Nam giải quyết.</p>', '2026-10-29 00:00:00', '2026-10-29 00:00:00');

INSERT INTO `migrations` (`migration`, `batch`)
SELECT m.name, (SELECT COALESCE(MAX(`batch`), 0) + 1 FROM `migrations`) FROM (
    SELECT '2026_11_16_000100_create_legal_pages_table' AS name
    UNION ALL SELECT '2026_11_17_000100_turn_legal_pages_into_cms'
) m WHERE NOT EXISTS (SELECT 1 FROM `migrations` x WHERE x.`migration` = m.name);
